WITH fixes(slug,pos,why) AS (VALUES ('legislacao-budapeste-revisao',2,'Correto. O art. 15 da Convenção de Budapeste determina que os poderes e procedimentos de investigação observem condições e garantias, incluindo proporcionalidade e proteção dos direitos humanos.'),('legislacao-budapeste-revisao',5,'Correto. O art. 16 da Convenção de Budapeste trata da preservação expedita de dados informáticos armazenados, para impedir sua perda ou alteração durante a investigação.'),('legislacao-identidade-revisao',1,'Errado. A carteira de identidade possui validade nacional, e não apenas no estado emissor. A afirmação confunde o órgão expedidor com o alcance territorial do documento.'),('legislacao-identidade-revisao',2,'Correto. A carteira de identidade tem validade em todo o território brasileiro; o estado que a emite não limita sua eficácia a esse estado.'),('legislacao-identidade-revisao',4,'Correto. A carteira de identidade faz prova dos dados de identificação nela constantes, observados os limites e requisitos da legislação pertinente.'),('legislacao-migracao-revisao',1,'Correto. O art. 61 da Lei 13.445/2017 proíbe a repatriação, deportação ou expulsão coletivas, exigindo análise individualizada da situação migratória.'),('legislacao-terrorismo-revisao',2,'Correto. O art. 11 da Lei 13.260/2016 atribui à Polícia Federal a investigação dos crimes nela previstos, considerados de interesse da União.'),('legislacao-trafico-pessoas-revisao',6,'Correto. O art. 149-A, IV, do Código Penal inclui a adoção ilegal entre as finalidades do tráfico de pessoas, desde que presentes os demais elementos do tipo penal.'),('legislacao-seguranca-privada-revisao',7,'Correto. A prestação de serviços de segurança privada depende de autorização prévia da Polícia Federal, conforme a legislação específica aplicável.'),('legislacao-cin-revisao',1,'Correto. A Carteira de Identidade Nacional utiliza o CPF como número único de identificação, reduzindo a multiplicidade de registros estaduais.')), rebuilt AS (SELECT sm.id,jsonb_agg(CASE WHEN f.pos IS NOT NULL AND length(trim(coalesce(e.value->>'why','')))<25 THEN jsonb_set(e.value,'{why}',to_jsonb(f.why)) ELSE e.value END ORDER BY e.ordinality) quiz FROM study_materials sm CROSS JOIN LATERAL jsonb_array_elements(sm.quiz) WITH ORDINALITY e(value,ordinality) LEFT JOIN fixes f ON f.slug=sm.slug AND f.pos=e.ordinality WHERE sm.slug IN (SELECT DISTINCT slug FROM fixes) GROUP BY sm.id) UPDATE study_materials sm SET quiz=r.quiz,updated_at=now() FROM rebuilt r WHERE sm.id=r.id;